class TaskChain:
    """Headless dependency-tracking task graph with notifications."""

    def __init__(self):
        self._tasks = {}
        self._order = []
        self._events = []

    def _require(self, task_id):
        if task_id not in self._tasks:
            raise KeyError(task_id)
        return self._tasks[task_id]

    def add_task(self, task_id, dependencies=None):
        if task_id in self._tasks:
            raise ValueError("duplicate task id: %r" % (task_id,))
        deps = [] if dependencies is None else list(dependencies)
        for dep in deps:
            if dep not in self._tasks:
                raise KeyError(dep)
        self._tasks[task_id] = {
            "status": "pending",
            "dependencies": list(deps),
            "comments": [],
        }
        self._order.append(task_id)

    def start(self, task_id):
        task = self._require(task_id)
        if task["status"] != "pending":
            raise ValueError("task %r is not pending" % (task_id,))
        for dep in task["dependencies"]:
            if self._tasks[dep]["status"] != "completed":
                raise ValueError("dependency %r not completed" % (dep,))
        task["status"] = "in_progress"

    def complete(self, task_id):
        task = self._require(task_id)
        if task["status"] != "in_progress":
            raise ValueError("task %r is not in_progress" % (task_id,))
        task["status"] = "completed"
        self._events.append({"kind": "completed", "task_id": task_id})
        for candidate in self._order:
            other = self._tasks[candidate]
            if other["status"] != "pending":
                continue
            if task_id not in other["dependencies"]:
                continue
            unblocked = True
            for dep in other["dependencies"]:
                if self._tasks[dep]["status"] != "completed":
                    unblocked = False
                    break
            if unblocked:
                self._events.append({"kind": "unblocked", "task_id": candidate})

    def add_comment(self, task_id, author, text):
        task = self._require(task_id)
        task["comments"].append({"author": author, "text": text})

    def snapshot(self):
        result = {}
        for tid, task in self._tasks.items():
            comments = []
            for comment in task["comments"]:
                comments.append({"author": comment["author"], "text": comment["text"]})
            result[tid] = {
                "status": task["status"],
                "dependencies": list(task["dependencies"]),
                "comments": comments,
            }
        return result

    def notifications(self):
        out = []
        for event in self._events:
            out.append({"kind": event["kind"], "task_id": event["task_id"]})
        return out

    def report(self):
        buckets = {"pending": [], "in_progress": [], "completed": []}
        for tid, task in self._tasks.items():
            buckets[task["status"]].append(tid)
        for key in buckets:
            buckets[key].sort()
        return buckets

    def diagram(self):
        lines = ["graph TD"]
        for tid in self._order:
            lines.append("    " + str(tid))
        for tid in self._order:
